t.M("מהו הסימן המוקדם ביותר של היפרתרמיה ממאירה?", ["חום גבוה", "עלייה ב-EtCO2", "היפוטנסיה", "מיוגלובינוריה"], 1)
t.M("מה הטיפול בהיפרתרמיה ממאירה?", ["פרצטמול", "דנטרולן", "סוקצינילכולין", "בטא-חוסם"], 1)
t.N("כמה דקות לפני החתך יש לתת אנטיביוטיקה מניעתית (רוב התרופות)?", 60, 0, "דקות")
t.F("חום וכאב לא פרופורציונלי בפצע ביום הראשון אחרי ניתוח. מה החשש?", "זיהום נמקי של רקמות רכות (Strep קבוצה A או Clostridium). דורש הטריה כירורגית דחופה.")
t.M("איזה סיווג פצע מתאים לכריתת מעי גס אלקטיבית עם הכנה?", ["נקי", "נקי-מזוהם", "מזוהם", "מלוכלך"], 1)
